//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS21320.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 표준코드  아이디 발급현황 리스트 조회 
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ISSUEID_LIST_21320_INOUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.issueinfo.select.stdcdidlist.dyn" + "&{P}ISUR_CD=" + txb_pISUR_CD.getValue() + "&{P}ACTIV_YN=Y" + //활성여부
        "&{P}REG_DD_SDATE=" + scwin.fn_returnDate(edt_pREG_DD_SDATE) + "&{P}REG_DD_EDATE=" + scwin.fn_returnDate(edt_pREG_DD_EDATE);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};
scwin.arrPar = new Array();
/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달 값을 정의한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID  
    scwin.arrPar[1] = txb_param2.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_AllUnCheck
 * 설명       : 비활성된 값인치 체크하여 값을 출력 
 ***********************************************/
scwin.fn_returnDate = function(Obj) {
    return (Obj.enable == true) ? Obj.getText() : "";
};
scwin.fn_Init = function() {
    $c.stf.setObjectValue(edt_pREG_DD_SDATE, $c.ut.cGetMinusYear($c.ut.cGetToday2(), 1)); // 1년 셋팅
    $c.stf.setObjectValue(edt_pREG_DD_EDATE, $c.ut.cGetToday2());
};
scwin.gform_onload = function() {
    //날짜셋팅
    scwin.fn_Init();
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_pISUR_CD_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISUR_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "표준코드 아이디 발급현황 목록", "", "8");
};
scwin.img_pREG_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pREG_DD_SDATE);
};
scwin.img_pREG_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pREG_DD_EDATE);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    scwin.fn_Init();
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    if (vTp == 7) {
        //전체
        $c.stf.setObjectValue(edt_pREG_DD_SDATE, '00010101');
        $c.stf.setObjectValue(edt_pREG_DD_EDATE, '99991231');
    } else {
        $c.stf.fn_setFromToDate(vTp, edt_pREG_DD_SDATE, edt_pREG_DD_EDATE);
    }
};
